\subsection{Mathematical Formulation}

\subsubsection{Sets and Indices}
 egin{itemize}
\item $L$: candidate transit or shuttle lines
\item $N$: network nodes or stops
\item $C$: origin-destination demand pairs
\end{itemize}

\subsubsection{Parameters}
 egin{itemize}
\item $fc_l$: fixed cost of activating line $l$
\item $oc_l$: operating cost per unit frequency on line $l$
\item $cap_l$: passenger capacity delivered by one unit of frequency on line $l$
\item $tt_l$: vehicle-hours consumed by one unit of frequency on line $l$
\item $min_l, max_l$: minimum and maximum frequency if line $l$ is selected
\item $d_c$: demand for OD pair $c$
\item $p_c$: penalty per unit unmet demand for OD pair $c$
\item $service_{lc}$: 1 if line $l$ can serve OD pair $c$
\item $pass_{ln}$: 1 if line $l$ passes through node $n$
\item $r_n$: fixed parameter equal to 1 if node $n$ requires transfer coverage, else 0
\item $V$: available total vehicle-hours
\end{itemize}

\subsubsection{Decision Variables}
 egin{itemize}
\item $x_l \in \{0,1\}$: whether candidate line $l$ is activated
\item $f_l \ge 0$: continuous service frequency of line $l$
\item $s_c \ge 0$: unmet demand for OD pair $c$
\end{itemize}

\subsubsection{Objective}
 egin{equation}
\min \sum_{l \in L} (fc_l x_l + oc_l f_l) + \sum_{c \in C} p_c s_c
\end{equation}

\subsubsection{Constraints}
 egin{enumerate}
\item Demand coverage with possible unmet demand: $\sum_{l \in L} cap_l service_{lc} f_l + s_c \ge d_c$ for all $c \in C$.
\item Frequency activation linking: $f_l \le max_l x_l$ and $f_l \ge min_l x_l$ for all $l \in L$.
\item Fleet vehicle-hours budget: $\sum_{l \in L} tt_l f_l \le V$.
\item Required transfer-node line coverage: $\sum_{l \in L} pass_{ln} x_l \ge 2r_n$ for all $n \in N$.
\end{enumerate}

There are no passenger-flow variables, vehicle routes, time windows, subtour constraints, or arc-use variables in this generator.
